-- platform#49: app role must not DELETE gear_op_noop_ids directly.
-- Sweeper uses SECURITY DEFINER public.prune_gear_op_noop_ids (012). Default privileges
-- for crusaderstrike_migrate may have granted DELETE on the table; revoke it.
-- Applied migrations are immutable: do not edit this file after it has been applied;
-- ship a new numbered migration instead (see src/db/migrate.ts checksum guard).
REVOKE DELETE ON public.gear_op_noop_ids FROM crusaderstrike_app;

-- Document silent upper clamps inside prune_gear_op_noop_ids (012): days > 3650 → 3650,
-- limit > 100000 → 100000; values < 1 still RAISE.
COMMENT ON FUNCTION public.prune_gear_op_noop_ids(integer, integer) IS
  'SECURITY DEFINER sweeper for expired gear_op_noop_ids. Uses now() only. '
  'Silently clamps retention_days to at most 3650 and limit to at most 100000; '
  'raises if either argument is NULL or < 1.';
